  523	func diff(curResults, preResults models.ScanResults, includeChanges ...bool) (diffed models.ScanResults, err error) {
  524		// Calls without explicit filters retain the previous plus-only helper behavior.
  525		includePlus, includeMinus := true, false
  526		markStatus := len(includeChanges) > 0
  527		if len(includeChanges) > 0 {
  528			includePlus = includeChanges[0]
  529		}
  530		if len(includeChanges) > 1 {
  531			includeMinus = includeChanges[1]
  532		}
  533	
  534		for _, current := range curResults {
  535			found := false
  536			var previous models.ScanResult
  537			for _, r := range preResults {
  538				if current.ServerName == r.ServerName && current.Container.Name == r.Container.Name {
  539					found = true
  540					previous = r
  541					break
  542				}
  543			}
  544	
  545			if found {
  546				current.ScannedCves = getDiffCves(previous, current, includePlus, includeMinus)
  547				if !markStatus {
  548					for id, vuln := range current.ScannedCves {
  549						vuln.DiffStatus = ""
  550						current.ScannedCves[id] = vuln
  551					}
  552				}
  553				packages := models.Packages{}
  554				for _, vuln := range current.ScannedCves {
  555					sourcePackages := current.Packages
  556					if vuln.DiffStatus == models.DiffMinus {
  557						sourcePackages = previous.Packages
  558					}
  559					for _, affected := range vuln.AffectedPackages {
  560						if pkg, ok := sourcePackages[affected.Name]; ok {
  561							packages[affected.Name] = pkg
  562						}
  563					}
  564				}
  565				current.Packages = packages
  566			}
  567	
  568			diffed = append(diffed, current)
  569		}
  570		return diffed, err
  571	}
