  573	func getDiffCves(previous, current models.ScanResult, includePlus, includeMinus bool) models.VulnInfos {
  574		diffed := models.VulnInfos{}
  575		for cveID, vuln := range current.ScannedCves {
  576			if _, found := previous.ScannedCves[cveID]; found {
  577				continue
  578			}
  579			if includePlus {
  580				vuln.DiffStatus = models.DiffPlus
  581				diffed[cveID] = vuln
  582				util.Log.Debugf("new: %s", vuln.CveID)
  583			}
  584		}
  585	
  586		for cveID, vuln := range previous.ScannedCves {
  587			if _, found := current.ScannedCves[cveID]; found {
  588				continue
  589			}
  590			if includeMinus {
  591				vuln.DiffStatus = models.DiffMinus
  592				diffed[cveID] = vuln
  593				util.Log.Debugf("resolved: %s", vuln.CveID)
  594			}
  595		}
  596	
  597		if len(diffed) == 0 {
  598			util.Log.Infof("%s: There are %d vulnerabilities, but no requested changes between current and previous results.", current.FormatServerName(), len(current.ScannedCves))
  599		}
  600		return diffed
  601	}
